begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into auth.users(id,email) values ('84000000-0000-4000-8000-000000000001','payment-admin@example.invalid');
insert into public.profiles(id,full_name,role) values ('84000000-0000-4000-8000-000000000001','Payment test admin','admin') on conflict(id) do update set role='admin';
insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) values ('84000000-0000-4000-8000-000000000002','84000000-0000-4000-8000-000000000001','totp','verified','LOCAL-TEST-ONLY',now(),now());
insert into public.staff_orders(id,order_number,booking_date,booking_time,players_count,total,subtotal) values ('84000000-0000-4000-8000-000000000003','PAYMENT-TEST',current_date,'10:00',1,100000,100000);
select ok(not has_function_privilege('anon','public.staff_record_order_payment(uuid,uuid,text,integer)','execute'),'Anonymous callers cannot record receipts');
select ok(not (select prosecdef from pg_proc where oid='public.staff_record_order_payment(uuid,uuid,text,integer)'::regprocedure),'Payment recording retains row-level security');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"84000000-0000-4000-8000-000000000001","is_anonymous":false,"aal":"aal1"}',true);
select throws_ok($q$select public.staff_record_order_payment('84000000-0000-4000-8000-000000000003','84000000-0000-4000-8000-000000000011','cash',40000)$q$,'P0001','Staff access required.','AAL1 admin cannot record money');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"84000000-0000-4000-8000-000000000001","is_anonymous":true,"aal":"aal2"}',true);
select throws_ok($q$select public.staff_record_order_payment('84000000-0000-4000-8000-000000000003','84000000-0000-4000-8000-000000000011','cash',40000)$q$,'P0001','Staff access required.','Anonymous Auth sessions cannot record money');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"84000000-0000-4000-8000-000000000001","is_anonymous":false,"aal":"aal2"}',true);
select lives_ok($q$select public.staff_record_order_payment('84000000-0000-4000-8000-000000000003','84000000-0000-4000-8000-000000000011','cash',40000)$q$,'Named AAL2 staff can record partial payment');
select is((select payment_status from public.staff_orders where order_number='PAYMENT-TEST'),'partially_paid','Partial receipt updates order status');
select lives_ok($q$select public.staff_record_order_payment('84000000-0000-4000-8000-000000000003','84000000-0000-4000-8000-000000000011','cash',40000)$q$,'Retry is safe');
select is((select count(*)::integer from public.staff_order_payments where order_id='84000000-0000-4000-8000-000000000003'),1,'Retry does not duplicate money');
select throws_ok($q$select public.staff_record_order_payment('84000000-0000-4000-8000-000000000003','84000000-0000-4000-8000-000000000011','cash',50000)$q$,'P0001','This receipt reference was already used for a different payment.','Changed retry payload is rejected');
select throws_ok($q$select public.staff_record_order_payment('84000000-0000-4000-8000-000000000003','84000000-0000-4000-8000-000000000012','cash',70000)$q$,'P0001','Payment exceeds the remaining balance. Refresh the order and check the amount.','Cannot overpay remaining balance');
select is((select count(*)::integer from public.staff_order_payments where order_id='84000000-0000-4000-8000-000000000003'),1,'Rejected payment leaves no receipt');
select lives_ok($q$select public.staff_record_order_payment('84000000-0000-4000-8000-000000000003','84000000-0000-4000-8000-000000000012','bank_transfer',60000)$q$,'Balance can be paid by another method');
select is((select payment_status || '/' || payment_method from public.staff_orders where order_number='PAYMENT-TEST'),'paid/split','Order reconciles fully paid cash and bank receipts');
select is((select sum(amount)::integer from public.staff_order_payments where order_id='84000000-0000-4000-8000-000000000003'),100000,'Ledger matches amount paid');
update public.staff_orders set order_status='cancelled' where order_number='PAYMENT-TEST';
select throws_ok($q$select public.staff_record_order_payment('84000000-0000-4000-8000-000000000003','84000000-0000-4000-8000-000000000013','cash',1)$q$,'P0001','Payments cannot be added to this order status.','Cancelled orders cannot collect a new payment');
reset role;
select * from finish();
rollback;
